"""Parsing visits from text."""
from visits import Visit


def _parse_line(line):
    page, minutes = line.split(",")
    return Visit(page.strip(), int(minutes))


def parse_visits(text):
    """Parse lines of 'page,minutes' into Visit records. Blank lines are skipped."""
    out = []
    line = ""
    for ch in text:
        if ch == "\n":
            if line.strip():
                out.append(_parse_line(line))
            line = ""
        else:
            line += ch
    return out


def largest_minutes(visits):
    """Return the largest minutes, or None when there are no visits."""
    values = [x.minutes for x in visits]
    return max(values) if values else None


def describe_visit(visit):
    """Return a one-line description of a visit."""
    return "%s: %s" % (visit.page, visit.minutes)

